package com.peiwan.platform.system;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.peiwan.platform.persistence.entity.*;import com.peiwan.platform.persistence.mapper.*;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;
@Component public class BootstrapData implements CommandLineRunner{private final SystemUserMapper users;private final SystemRoleMapper roles;private final SystemRelationMapper relations;private final PasswordEncoder encoder;private final String initialPassword;public BootstrapData(SystemUserMapper u,SystemRoleMapper r,SystemRelationMapper x,PasswordEncoder e,@Value("${ADMIN_INITIAL_PASSWORD:}")String p){users=u;roles=r;relations=x;encoder=e;initialPassword=p;}
 public void run(String...args){var admin=users.selectOne(new QueryWrapper<SystemUserEntity>().eq("username","admin"));if(admin==null){if(initialPassword.isBlank()){LoggerFactory.getLogger(getClass()).warn("未创建管理员：请设置 ADMIN_INITIAL_PASSWORD 后重启");return;}admin=new SystemUserEntity();admin.username="admin";admin.password=encoder.encode(initialPassword);admin.nickname="超级管理员";admin.email="admin@peiwan.local";admin.gender="未知";admin.enabled=true;users.insert(admin);}var role=roles.selectOne(new QueryWrapper<SystemRoleEntity>().eq("code","admin"));if(role==null)throw new IllegalStateException("Flyway 未初始化 admin 角色");if(relations.hasUserRole(admin.id,role.id)==0)relations.addUserRole(admin.id,role.id);relations.grantAllMenus(role.id);}
}
